<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= htmlspecialchars($story['title'] ?? 'Stories') ?> | Lokal Culture</title><meta name="description" content="Stories of Indian craft, makers, regions and cultural practice from Lokal Culture."><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/catalog.css"></head>
